export type NotionAssetManifest = Record<string, string>

export type NotionAssetStats = {
  originalBytes: number
  displayBytes: number
  thumbnailBytes: number
  uniqueSourceImages: number
  duplicateMappings: number
}

export type NotionIndex = {
  rootPageId: string
  generatedAt: string | null
  pages: NotionIndexPage[]
  assetStats?: NotionAssetStats
}

const REMOTE_INDEX =
  'https://raw.githubusercontent.com/gkzero0-cmyk/justserver3/main/public/notion-assets/index.json?v=20260925-4'

const EMPTY_INDEX: NotionIndex = {
  rootPageId: '3dad57d6a55c80469f3de9730cb88975',
  generatedAt: null,
  pages: []
}

function readLocalIndex(): NotionIndex {
  try {
    const indexPath = path.join(
      process.cwd(),
      'public',
      'notion-assets',
      'index.json'
    )

    return JSON.parse(fs.readFileSync(indexPath, 'utf8')) as NotionIndex
  } catch {
    return EMPTY_INDEX
  }
}

export async function readNotionIndex(): Promise<NotionIndex> {
  try {
    const response = await fetch(REMOTE_INDEX, {
      headers: {
        'Cache-Control': 'no-cache'
      },
      next: {
        revalidate: 60,
        tags: ['notion-index']
      }
    })
    if (!response.ok) throw new Error(`HTTP ${response.status}`)
    return (await response.json()) as NotionIndex
  } catch {
    return readLocalIndex()
  }
}


const REMOTE_MANIFEST =
  'https://raw.githubusercontent.com/gkzero0-cmyk/justserver3/main/public/notion-assets/display-manifest.json?v=20260925-4'
const FALLBACK_MANIFEST =
  'https://raw.githubusercontent.com/gkzero0-cmyk/justserver3/main/public/notion-assets/manifest.json?v=20260925-4'

function readLocalManifest(): NotionAssetManifest {
  try {
    const manifestPath = path.join(
      process.cwd(),
      'public',
      'notion-assets',
      'manifest.json'
    )

    return JSON.parse(
      fs.readFileSync(manifestPath, 'utf8')
    ) as NotionAssetManifest
  } catch {
    return {}
  }
}

export async function readNotionAssetManifest(): Promise<NotionAssetManifest> {
  try {
    const response = await fetch(REMOTE_MANIFEST, {
      headers: {
        'Cache-Control': 'no-cache'
      },
      next: {
        revalidate: 60,
        tags: ['notion-assets']
      }
    })

    if (response.ok) {
      return (await response.json()) as NotionAssetManifest
    }

    const fallback = await fetch(FALLBACK_MANIFEST, {
      headers: {
        'Cache-Control': 'no-cache'
      },
      next: {
        revalidate: 60,
        tags: ['notion-assets']
      }
    })
    if (!fallback.ok) throw new Error(`HTTP ${fallback.status}`)
    return (await fallback.json()) as NotionAssetManifest
  } catch {
    return readLocalManifest()
  }
}

import { unstable_cache } from 'next/cache'
import { NotionAPI } from 'notion-client'

const notion = new NotionAPI()

export const ROOT_PAGE_ID =
  process.env.NOTION_PAGE_ID ?? '3dad57d6a55c80469f3de9730cb88975'

const getPage = async (pageId: string) => notion.getPage(pageId)

export const getNotionPage = unstable_cache(getPage, ['notion-page'], {
  revalidate: 3600,
  tags: ['notion-page']
})

export const notionPublicUrl = (pageId: string) =>
  `https://daisy-grouse-ac0.notion.site/${pageId.replaceAll('-', '')}`

export function getSiteUrl() {
  const explicit = process.env.NEXT_PUBLIC_SITE_URL?.trim()
  if (explicit) return explicit.replace(/\/$/, '')

  const production = process.env.VERCEL_PROJECT_PRODUCTION_URL?.trim()
  if (production) return `https://${production.replace(/\/$/, '')}`

  const preview = process.env.VERCEL_URL?.trim()
  if (preview) return `https://${preview.replace(/\/$/, '')}`

  return 'http://localhost:3000'
}

export const BASE_PATH = process.env.NEXT_PUBLIC_BASE_PATH?.replace(/\/$/, '') ?? ''

const CDN_ASSET_ORIGIN =
  'https://cdn.jsdelivr.net/gh/gkzero0-cmyk/justserver3@main/public'

export function withBasePath(pathname: string) {
  if (!pathname.startsWith('/')) return pathname
  if (!BASE_PATH) return pathname
  if (pathname === '/') return `${BASE_PATH}/`
  return `${BASE_PATH}${pathname}`
}

export function deriveOptimizedVariant(
  pathname: string | null | undefined,
  kind: 'thumb256' | 'hero768' | 'hero1280' | 'hero1600'
) {
  if (!pathname) return null

  const match = pathname.match(
    /\/notion-assets\/optimized\/(?:[^/]+\/)?([0-9a-f]{24})\.webp$/i
  )
  if (!match) return null

  return `/notion-assets/optimized/${kind}/${match[1]}.webp`
}

export function resolveCachedAsset(pathname: string) {
  if (/^https?:\/\//i.test(pathname)) return pathname
  if (pathname.startsWith('/notion-assets/')) {
    return `${CDN_ASSET_ORIGIN}${pathname}`
  }
  return withBasePath(pathname)
}

export function getSiteUrl() {
  const explicit = process.env.NEXT_PUBLIC_SITE_URL?.trim()
  if (explicit) return explicit.replace(/\/$/, '')

  const production = process.env.VERCEL_PROJECT_PRODUCTION_URL?.trim()
  if (production) return `https://${production.replace(/\/$/, '')}`

  const preview = process.env.VERCEL_URL?.trim()
  if (preview) return `https://${preview.replace(/\/$/, '')}`

  return 'http://localhost:3000'
}

export type WikiCategoryKey = 'start' | 'content' | 'growth'

export const WIKI_CATEGORIES: Record<
  WikiCategoryKey,
  { title: string; icon: string; description: string }
> = {
  start: {
    title: '시작하기',
    icon: '🧭',
    description: '처음 접속하기 전에 확인할 필수 안내'
  },
  content: {
    title: '주요 콘텐츠',
    icon: '🎮',
    description: '채광부터 도감·파쿠르·미니게임까지'
  },
  growth: {
    title: '성장 · 경제',
    icon: '📈',
    description: '땅, 빚, 신용등급, 장비 성장과 FAQ'
  }
}

export function categoryForTitle(title: string): WikiCategoryKey {
  const value = title.toLowerCase()

  if (
    value.includes('스토리') ||
    value.includes('규칙') ||
    value.includes('패치') ||
    value.includes('api') ||
    value.includes('뉴비') ||
    value.includes('기초')
  ) {
    return 'start'
  }

  if (
    value.includes('땅') ||
    value.includes('빚') ||
    value.includes('신용') ||
    value.includes('수리') ||
    value.includes('강화') ||
    value.includes('물어보는')
  ) {
    return 'growth'
  }

  return 'content'
}

export function iconForTitle(title: string) {
  const value = title.toLowerCase()

  if (value.includes('스토리')) return '📖'
  if (value.includes('룰') || value.includes('규칙')) return '📜'
  if (value.includes('api') || value.includes('후원')) return '💝'
  if (value.includes('뉴비') || value.includes('기초')) return '🧭'
  if (value.includes('패치')) return '📝'
  if (value.includes('강화')) return '⚒️'
  if (value.includes('수리')) return '🔧'
  if (value.includes('광') || value.includes('채광')) return '⛏️'
  if (value.includes('낚시')) return '🎣'
  if (value.includes('도축')) return '🥩'
  if (value.includes('사냥')) return '⚔️'
  if (value.includes('요리')) return '🍳'
  if (value.includes('도감')) return '📚'
  if (value.includes('파쿠르')) return '🏃'
  if (value.includes('복권')) return '🎟️'
  if (value.includes('경마')) return '🏇'
  if (value.includes('카지노')) return '🎰'
  if (value.includes('땅')) return '🏠'
  if (value.includes('빚')) return '💸'
  if (value.includes('신용')) return '💳'
  if (value.includes('물어보는')) return '❓'

  return '✦'
}

export function categoryTitleForPage(title: string) {
  return WIKI_CATEGORIES[categoryForTitle(title)].title
}

export function categoryAnchorForTitle(title: string) {
  return `category-${categoryForTitle(title)}`
}

import type { NotionIndexPage } from '@/lib/notion-index'

const PLACEHOLDER_PATTERN = /위키\s*업데이트\s*예정|내용\s*추가\s*예정|작성\s*중/i

export function isDraftPage(page: Pick<NotionIndexPage, 'searchText'>) {
  const text = (page.searchText || '').replace(/\s+/g, ' ').trim()
  return PLACEHOLDER_PATTERN.test(text) || text.length < 80
}

